<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Category; use App\Models\Product; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\View\View;
class ProductController extends Controller { public function index(): View { return view('admin.products.index',['products'=>Product::with('category')->latest()->paginate(20)]); } public function create(): View { return view('admin.products.form',['product'=>new Product,'categories'=>Category::with('parent.parent')->get()]); } public function store(Request $r): RedirectResponse { Product::create($this->data($r)); return to_route('admin.products.index')->with('success','Product created.'); } public function edit(Product $product): View { return view('admin.products.form',['product'=>$product,'categories'=>Category::with('parent.parent')->get()]); } public function update(Request $r,Product $product): RedirectResponse { $product->update($this->data($r,$product)); return to_route('admin.products.index')->with('success','Product updated.'); } public function destroy(Product $product): RedirectResponse { $product->delete(); return back()->with('success','Product removed.'); } private function data(Request $r,?Product $product=null): array { $d=$r->validate(['category_id'=>'required|exists:categories,id','name'=>'required|max:150','description'=>'required','price'=>'required|numeric|min:1','compare_at_price'=>'nullable|numeric|min:1','image'=>'required|url|max:500','color'=>'required|max:60','material'=>'required|max:100','width'=>'required|max:60','stock'=>'required|integer|min:0','is_featured'=>'nullable','is_new'=>'nullable']); $d['slug']=Str::slug($d['name']).($product?'':'-'.Str::lower(Str::random(4))); $d['is_featured']=$r->boolean('is_featured');$d['is_new']=$r->boolean('is_new');return $d; } }
